import queue
import threading


def run_pool(items, fn, workers=3):
    q = queue.Queue()
    for it in items:
        q.put(it)
    out, lock = [], threading.Lock()

    def work():
        while True:
            try:
                it = q.get_nowait()
            except queue.Empty:
                return
            r = fn(it)
            with lock:
                out.append(r)

    ts = [threading.Thread(target=work) for _ in range(workers)]
    for t in ts:
        t.start()
    for t in ts:
        t.join()
    return out

