class Perceptron:
    def __init__(self, n, lr=0.1):
        self.w = [0.0] * n
        self.b = 0.0
        self.lr = lr

    def predict(self, x):
        return 1 if sum(w * v for w, v in zip(self.w, x)) + self.b > 0 else 0

    def fit(self, X, y, epochs=50):
        for _ in range(epochs):
            for x, t in zip(X, y):
                e = t - self.predict(x)
                if e:
                    self.w = [w + self.lr * e * v for w, v in zip(self.w, x)]
                    self.b += self.lr * e

